.dm-hnx{padding:12px;display:flex;flex-direction:column;gap:6px}
.dm-hnx-h{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:2px 10px 8px}
.dm-hnx-h>div{display:flex;flex-direction:column}
.dm-hnx-h b{font-weight:500;font-size:13.5px}
.dm-hnx-st{font-size:12px}
.dm-hnx-list{display:flex;flex-direction:column}
.dm-hnx-t{display:flex;align-items:center;gap:12px;padding:8px 10px;border-radius:12px;font-size:13px;transition:background .2s}
.dm-hnx-t:hover{background:var(--dm-row)}
.dm-hnx-t .dm-ic{width:28px;height:28px;border-radius:9px;display:grid;place-items:center;flex:none;position:relative}
.dm-hnx-t .dm-ic::after{content:"";position:absolute;right:-2px;bottom:-2px;width:8px;height:8px;border-radius:50%;background:var(--dm-ok);box-shadow:0 0 0 2px var(--dm-surface);transition:background .3s}
.dm-hnx-t.dm-off .dm-ic::after{background:var(--dm-faint)}
.dm-hnx-t .dm-ic.dm-brandic{background:var(--dm-surface);box-shadow:inset 0 0 0 1px var(--dm-line);color:var(--dm-fg)}
.dm-hnx-t .dm-ic .dm-brand{width:15px;height:15px}
.dm-hnx-t.dm-err .dm-ic::after{background:var(--dm-bad)}
.dm-hnx-t.dm-chk .dm-ic::after{background:var(--dm-accent);animation:dm-hnp 1s ease-in-out infinite}
@keyframes dm-hnp{50%{transform:scale(1.4);opacity:.5}}
.dm-hnx-t .dm-t{flex:1;min-width:0;display:flex;flex-direction:column}
.dm-hnx-t .dm-t span{font-size:12px;color:var(--dm-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dm-hnx-t.dm-err .dm-t span{color:var(--dm-bad)}
.dm-hnx-pm{display:grid;grid-template-columns:repeat(3,auto);padding:2px;border-radius:9px;background:var(--dm-chip);position:relative}
.dm-hnx-pm button{position:relative;z-index:1;height:24px;padding:0 8px;font-size:11.5px;color:var(--dm-muted);transition:color .2s}
.dm-hnx-pm button[aria-pressed="true"]{color:var(--dm-fg)}
.dm-hnx-pm .dm-kn{position:absolute;top:2px;bottom:2px;border-radius:7px;background:var(--dm-surface);box-shadow:0 1px 2px rgba(0,0,0,.08);transition:left .4s var(--dm-ease),width .4s var(--dm-ease)}
.dm-hnx-add{display:flex;align-items:center;gap:8px;padding:8px 10px;font-size:12.5px;color:var(--dm-fg2);border-radius:10px;align-self:flex-start}
.dm-hnx-add:hover{color:var(--dm-fg);background:var(--dm-chip)}
.dm-hnx-pop{min-width:220px}

